{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded SQL administrator password",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "HIGH",
      "explanation": "The SQL administrator password is embedded directly in the Terraform source, exposing it to source control readers and repository history."
    },
    {
      "check_id": "CKV_AZURE_52",
      "title": "Minimum TLS version is not explicitly enforced",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not explicitly require TLS 1.2, which could allow the effective encryption policy to depend on platform defaults."
    },
    {
      "check_id": "CKV_AZURE_113",
      "title": "SQL server public network access is enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Public network access is not disabled, leaving the SQL server reachable through its public endpoint subject to firewall configuration."
    },
    {
      "check_id": "CKV2_AZURE_27",
      "title": "Azure AD authentication is not enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no Azure AD administrator configured and relies on SQL authentication, preventing centralized identity and conditional-access controls."
    },
    {
      "check_id": "CKV2_AZURE_45",
      "title": "SQL server has no private endpoint",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "No private endpoint connects the SQL server to a private subnet, so private network access is not available when the public endpoint is disabled."
    },
    {
      "check_id": "CKV2_AZURE_2",
      "title": "SQL vulnerability assessment is not enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no vulnerability assessment configured with storage, so recurring database security scans and findings are unavailable."
    },
    {
      "check_id": "CKV_AZURE_23",
      "title": "SQL server auditing is not enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "No extended auditing policy is attached to the SQL server, reducing visibility into database activity and security investigations."
    },
    {
      "check_id": "CKV_AZURE_24",
      "title": "SQL audit retention is not greater than 90 days",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Because no auditing policy exists, the server does not retain audit records for more than 90 days as required."
    }
  ],
  "patched_code": "variable "mssql_administrator_password" {
  description = "SQL administrator password used during server provisioning."
  type        = string
  sensitive   = true
}

variable "mssql_aad_administrator_login_username" {
  description = "Login name of the Azure AD administrator for the SQL server."
  type        = string
}

variable "mssql_aad_administrator_object_id" {
  description = "Object ID of the Azure AD user, group, or service principal that administers the SQL server."
  type        = string
}

variable "mssql_aad_administrator_tenant_id" {
  description = "Azure AD tenant ID containing the SQL server administrator."
  type        = string
}

variable "mssql_private_endpoint_subnet_id" {
  description = "ID of the subnet in which the SQL server private endpoint will be created."
  type        = string
}

variable "mssql_security_storage_endpoint" {
  description = "Primary blob endpoint of the secured storage account used for SQL auditing and security data."
  type        = string
}

variable "mssql_security_storage_access_key" {
  description = "Access key for the storage account used for SQL auditing and vulnerability assessment."
  type        = string
  sensitive   = true
}

variable "mssql_vulnerability_assessment_storage_container_path" {
  description = "Full blob container path used to store SQL vulnerability assessment results."
  type        = string
}

resource "azurerm_mssql_server" "changeme_simple_mssql_server" {
  name                          = "changeme-simple-mssql-database-name"
  resource_group_name           = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name
  location                      = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location
  version                       = "12.0"
  administrator_login           = "changemeadmin"
  administrator_login_password  = var.mssql_administrator_password
  minimum_tls_version           = "1.2"
  public_network_access_enabled = false

  azuread_administrator {
    login_username              = var.mssql_aad_administrator_login_username
    object_id                   = var.mssql_aad_administrator_object_id
    tenant_id                   = var.mssql_aad_administrator_tenant_id
    azuread_authentication_only = true
  }
}

resource "azurerm_private_endpoint" "changeme_simple_mssql_server" {
  name                = "changeme-simple-mssql-private-endpoint"
  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name
  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location
  subnet_id           = var.mssql_private_endpoint_subnet_id

  private_service_connection {
    name                           = "changeme-simple-mssql-private-connection"
    private_connection_resource_id = azurerm_mssql_server.changeme_simple_mssql_server.id
    subresource_names              = ["sqlServer"]
